import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    m = int(data[1 + n])
    b = list(map(int, data[2 + n:2 + n + m]))
    i = j = 0
    res = []
    while i < n and j < m:
        if a[i] < b[j]:
            i += 1
        elif a[i] > b[j]:
            j += 1
        else:
            v = a[i]
            res.append(v)
            while i < n and a[i] == v:
                i += 1
            while j < m and b[j] == v:
                j += 1
    print(' '.join(map(str, res)) if res else -1)

